    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        state_prompts = {
            self.ws:
                self._configurations[self.connection_hops][self.proxy_pc][self.ws][
                    "command_params"]["expected_prompt"],
            self.ue_sim:
                self._configurations[self.connection_hops][self.ws][self.ue_sim][
                    "command_params"]["expected_prompt"],
            self.ws_root:
                self._configurations[self.connection_hops][self.ws][self.ws_root][
                    "command_params"]["expected_prompt"],
            self.schmmi:
                self._configurations[self.connection_hops][self.ws][self.schmmi][
                    "command_params"]["expected_prompt"]
        }
        return state_prompts

