    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(GenericRtgCus, self)._get_packages_for_state(state, observer)

        if not available:
            if state == self.ue_sim:
                available = {self.cmds: ['ta_moler.cmd.rtg.rtg'],
                             self.events: ['moler.events.shared', 'ta_moler.events.rtg.rtg']}
            if state == self.uesim_dump:
                available = {self.cmds: ['ta_moler.cmd.rtg.uesimdump'],
                             self.events: ['moler.events.shared']}
            if state == self.schmmi:
                available = {self.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix'],
                             self.events: ['moler.events.shared']}
            if available:
                return available[observer]

        return available
